import {LitElement,html,nothing,svg} from 'lit';
import {bingoApi} from './bingo-api.js';
import {activeGoal,generateBooks,gameSettings,MINIGAMES} from './bingo-model.js';
import {createBlock,planIssues} from './plan-model.js';
import {showBrand} from './show-brands.js';
import {DEMO_KEY,createRehearsal,demoStart,demoDraw,demoClaim,demoSettle,demoAdvance,formatShowDate,readiness} from './studio-hub-model.js';
const icons={grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',calendar:'M4 5h16v16H4zM8 2v6M16 2v6M4 11h16',play:'m9 5 11 7-11 7Z',book:'M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3zM12 6v16',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3M16 3a4 4 0 0 1 0 8M22 21v-3a4 4 0 0 0-3-4M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z',settings:'M3 7h18M3 17h18M8 4v6M16 14v6',arrow:'M4 12h16M14 6l6 6-6 6',chevron:'m9 5 7 7-7 7',check:'m5 12 4 4L19 6',plus:'M12 4v16M4 12h16',close:'m6 6 12 12M6 18 18 6',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',screen:'M2 3h20v14H2zM12 17v4M7 21h10',gift:'M3 8h18v4H3zM5 12v9h14v-9M12 8v13M12 8H8a3 3 0 1 1 3-3ZM12 8h4a3 3 0 1 0-3-3Z',clock:'M12 7v5l3 2M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20',info:'M12 11v6M12 7v1M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20',pause:'M8 5v14M16 5v14',search:'M21 21l-5-5M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14',menu:'M4 6h16M4 12h16M4 18h16',music:'M9 18V5l11-2v13M9 14c-6-2-7 6-2 6 2 0 2-2 2-2M20 12c-6-2-7 6-2 6 2 0 2-2 2-2',undo:'M4 10a8 8 0 1 1 1 9M4 4v6h6',up:'m6 14 6-6 6 6',down:'m6 10 6 6 6-6'};
const icon=(key)=>svg`<svg class="ico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d=${icons[key]||icons.spark}/></svg>`;
const names={overview:'Overzicht',shows:'Mijn shows',prepare:'Show voorbereiden',books:'Boekjes & spelers',live:'Live regie',player:'Spelersapp',library:'Showbibliotheek',settings:'Instellingen',analysis:'Concept & redesign'};
const status=s=>({draft:'In voorbereiding',running:'Show bezig',finished:'Afgelopen'}[s]||s);
const mini=p=>html`<span class="pattern" aria-label=${p?.title||'Patroon'}>${Array.from({length:25},(_,i)=>html`<i class=${p?.cells?.includes(i)?'on':i===12?'free':''}>${i===12?'✦':''}</i>`)}</span>`;
export class StudioHub extends LitElement {
 static properties={route:{},tab:{},demo:{type:Boolean},data:{state:true},game:{state:true},games:{state:true},loading:{state:true},busy:{state:true},message:{state:true},error:{state:true},modal:{state:true},search:{state:true},filter:{state:true},mobile:{state:true},playerTab:{state:true},selectedBook:{state:true},now:{state:true},libraryTab:{state:true},editBlock:{state:true},dirty:{state:true},draft:{state:true},shot:{state:true}};
 constructor(){super();const p=new URLSearchParams(location.search);this.demo=p.get('demo')==='1';this.output=p.get('screen')==='1';this.route=Object.hasOwn(names,location.hash.slice(1))?location.hash.slice(1):'overview';this.tab='draaiboek';this.playerTab='show';this.libraryTab='hosts';this.games=[];this.loading=true;this.game=null;this.data=null;this.now=Date.now();this.search='';this.filter='all';this.modal='';this.error='';this.message='';this.mobile=false;this.busy=false;this.selectedBook=0;this.shot='master';this.dirty=false;this.regieId=crypto.randomUUID();this._nav=()=>{const next=Object.hasOwn(names,location.hash.slice(1))?location.hash.slice(1):'overview';if(next!==this.route){this.filter='all';this.search='';}this.route=next;this.mobile=false;};this._sync=e=>{if(e.key===DEMO_KEY&&this.demo&&!this.dirty){this.restoreDemo();}};}
 createRenderRoot(){return this;}
 firstUpdated(){this.querySelector('.boot')?.remove();}
 connectedCallback(){super.connectedCallback();addEventListener('hashchange',this._nav);addEventListener('storage',this._sync);this.load();this.timer=setInterval(()=>{this.now=Date.now();if(this.demo&&!this.output&&this.data?.game.state.window?.status==='open'&&this.now>=this.data.game.state.window.endsAt){demoSettle(this.data);this.persist();}if(this.game&&!this.demo&&!this.dirty&&!this.busy&&this.now-(this.refreshed||0)>6000)this.refresh();},1000);}
 disconnectedCallback(){clearInterval(this.timer);removeEventListener('hashchange',this._nav);removeEventListener('storage',this._sync);super.disconnectedCallback();}
 go(route){if(route!==this.route&&['shows','books'].includes(route)){this.filter='all';this.search='';}if(route==='live'&&!this.demo){this.openRegie();return;}if(route==='player'&&!this.demo){location.href='/spelen'+(this.game?'?spel='+this.game.id:'');return;}location.hash=route;this.route=route;this.mobile=false;window.scrollTo({top:0,behavior:'instant'});}
 async load(){this.loading=true;this.error='';try{if(this.demo){this.restoreDemo();}else{const r=await bingoApi('/games');this.games=r.games;let selected=localStorage.getItem('vlampie-selected-game');const id=this.games.find(g=>g.status==='running')?.id||this.games.find(g=>g.id===selected)?.id||this.games[0]?.id;if(id)await this.selectGame(id);}}catch(e){this.error=e.message;}finally{this.loading=false;}}
 restoreDemo(){try{this.data=JSON.parse(localStorage.getItem(DEMO_KEY));if(this.data?.version!==40)this.data=null;}catch{}const fresh=!this.data;this.data??=createRehearsal();this.game=this.data.game;this.games=[this.summary(this.game)];if(fresh)this.persist();}
 summary(g){return {id:g.id,title:g.title,date:g.date,brandId:g.brandId,status:g.status,roundCount:g.plan.blocks.filter(b=>b.type==='round').length,bookCount:g.books.length,linked:g.books.filter(b=>b.accountId).length};}
 persist(){if(this.demo&&this.data){this.data.game=this.game;try{localStorage.setItem(DEMO_KEY,JSON.stringify(this.data));}catch{this.error='Je browser kan de oefenshow niet bewaren.';}this.games=[this.summary(this.game)];this.requestUpdate();}}
 async selectGame(id){if(this.dirty){this.error='Sla eerst je wijzigingen op.';return;}this.game=(await bingoApi('/games/'+id)).game;localStorage.setItem('vlampie-selected-game',id);this.refreshed=Date.now();this.draft=null;}
 async refresh(){this.refreshed=Date.now();try{const g=(await bingoApi('/games/'+this.game.id)).game;if(!this.dirty)this.game=g;}catch(e){this.error=e.message;}}
 async task(fn,success=''){if(this.busy)return;this.busy=true;this.error='';try{await fn();this.persist();if(success)this.message=success;}catch(e){this.error=e.message||'Dit lukte niet. Probeer opnieuw.';}finally{this.busy=false;}}
 async post(action,body={},method='POST'){const r=await bingoApi('/games/'+this.game.id+(action?'/'+action:''),{method,body:{...body,regieId:this.regieId}});if(r.game)this.game=r.game;return r;}
 mode(demo){if(this.dirty){this.error='Sla eerst je wijzigingen op.';return;}location.href=demo?'/?demo=1':'/';}
 openRegie(hash='regie'){if(this.game)localStorage.setItem('vlampie-selected-game',this.game.id);location.href='/regie#'+hash;}
 edit(){if(this.game.status!=='draft'&&!this.demo){this.error='De show is gestart. De instellingen staan vast.';return null;}if(!this.draft)this.draft=structuredClone(this.game);this.dirty=true;return this.draft;}
 async save(){await this.task(async()=>{if(!this.draft)return;this.draft.settings=gameSettings(this.draft.settings);const issues=planIssues(this.draft.plan);if(issues.length)throw Error(issues[0]);if(this.demo){const state=this.game.state;this.game={...this.draft,state};}else await this.post('',{plan:this.draft.plan,title:this.draft.title,date:this.draft.date,settings:this.draft.settings},'PUT');this.dirty=false;this.draft=null;},'Show opgeslagen.');}
 btn(label,action,kind='secondary',ico='',disabled=false){return html`<button class="btn ${kind}" @click=${action} ?disabled=${disabled||this.busy}>${ico?icon(ico):nothing}${label}</button>`;}
 render(){if(this.output&&this.game)return html`<div class="output-page">${this.stage()}<span class="output-note">OEFENSHOW · Alleen deze browser</span></div>`;const g=this.game;return html`
 <a href="#main" class="skip-link" @click=${e=>{e.preventDefault();this.querySelector('#main')?.focus();}}>Naar de inhoud</a>
 <aside class="sidebar ${this.mobile?'open':''}"><a class="brand" href="#overview"><span class="brand-monogram">V<span>✦</span></span><div>Vlampie<span>STUDIO</span></div></a><div class="workspace-switch"><span class="ws-icon">${icon('spark')}</span><div><strong>De showwerkplek</strong><small>Kinderbingo & entertainment</small></div></div><span class="nav-label">JOUW STUDIO</span><nav aria-label="Hoofdnavigatie">${[['overview','grid'],['shows','calendar'],['books','book'],['library','spark']].map(([r,i])=>html`<a href=${'#'+r} class=${this.route===r?'active':''} @click=${e=>{e.preventDefault();this.go(r);}}>${icon(i)}<span>${names[r]}</span>${r==='shows'&&this.games.length?html`<small>${this.games.length}</small>`:nothing}</a>`)}<span class="nav-label">TIJDENS DE SHOW</span>${[['live','screen'],['player','users']].map(([r,i])=>html`<a href=${this.demo?'#'+r:r==='live'?'/regie':'/spelen'} class=${this.route===r?'active':''} @click=${e=>{e.preventDefault();this.go(r);}}>${icon(i)}<span>${names[r]}</span>${r==='live'?html`<i class="live-dot"></i>`:nothing}</a>`)}</nav><div class="side-bottom"><a class=${this.route==='analysis'?'active':''} href="#analysis">${icon('info')}<span>Concept & redesign</span><small>V2</small></a><a href="#settings">${icon('settings')}<span>Instellingen</span></a><div class="side-user"><span class="avatar">DG</span><div><strong>Showbeheerder</strong><small>Vlampie Studio</small></div><span class="online-dot"></span></div></div></aside>
 ${this.mobile?html`<button class="menu-shade" aria-label="Menu sluiten" @click=${()=>this.mobile=false}></button>`:nothing}
 <div class="main-shell"><header class="topbar"><button class="icon-button mobile-menu" aria-label="Menu openen" @click=${()=>this.mobile=!this.mobile}>${icon('menu')}</button><div class="breadcrumb">Studio <span>/</span> <strong>${names[this.route]}</strong></div><div class="top-actions"><div class="mode-switch" aria-label="Omgeving"><button class=${!this.demo?'selected':''} @click=${()=>this.mode(false)}>Mijn shows</button><button class=${this.demo?'selected':''} @click=${()=>this.mode(true)}>Oefenshow</button></div><button class="icon-button" title="Concept en hulp" aria-label="Concept en hulp" @click=${()=>this.go('analysis')}>${icon('info')}</button><span class="avatar small">DG</span></div></header>
 ${this.demo?html`<div class="demo-strip"><span><i></i><strong>Oefenshow</strong><span>Voorbeeldgegevens · wijzigingen blijven in deze browser</span></span><button @click=${()=>this.modal='reset'}>${icon('undo')}Opnieuw</button></div>`:nothing}
 <main id="main" tabindex="-1"><div class="alert error" role="alert" ?hidden=${!this.error}>${icon('info')}<span>${this.error}</span><button aria-label="Sluiten" @click=${()=>this.error=''}>×</button></div>${this.loading?html`<div class="empty"><span class="spinner"></span><h2>Je studio wordt klaargezet</h2></div>`:this.renderPage()}</main><footer class="studio-footer"><span><b>Vlampie Studio</b> · Ruimte voor een geweldige show.</span><a href="#analysis">Wat is er vernieuwd? ${icon('arrow')}</a></footer></div>
 ${this.message?html`<div class="toast" role="status">${icon('check')}<span>${this.message}</span><button aria-label="Melding sluiten" @click=${()=>this.message=''}>×</button></div>`:nothing}${this.modal?this.renderModal():nothing}`;}
 renderPage(){switch(this.route){case'shows':return this.shows();case'prepare':return this.prepare();case'books':return this.books();case'library':return this.library();case'settings':return this.settings();case'analysis':return this.analysis();case'live':return this.live();case'player':return this.player();default:return this.overview();}}
 heading(kicker,title,copy,actions=nothing){return html`<div class="page-heading"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${copy}</p></div><div class="heading-actions">${actions}</div></div>`;}
 noGame(){return html`<div class="empty"><span class="empty-icon">${icon('calendar')}</span><h2>De eerste show begint bij jou.</h2><p>Maak een show aan, stel de rondes samen en nodig je spelers uit.</p><div class="button-row">${this.btn('Nieuwe show',()=>this.modal='create','primary','plus')}${this.btn('Ontdek de oefenshow',()=>this.mode(true),'secondary','play')}</div></div>`;}
 overview(){const g=this.game;return html`${this.heading('HET BEGINT ACHTER DE SCHERMEN','Een mooie show begint hier.','Alles voor jouw volgende kinderbingo, op één plek.',this.btn('Nieuwe show',()=>this.modal='create','primary','plus'))}
 ${!g?this.noGame():html`<div class="overview-grid"><section class="hero-card"><div class="hero-art" style=${'background-image:url('+showBrand(g).mascot+')'}></div><div class="hero-copy"><div class="hero-meta"><span class="badge gold">${status(g.status)}</span><span>JOUW VOLGENDE SHOW</span></div><h2>Een zaal vol<br>grote glimlachen<span>.</span></h2><p>${g.title}</p><div class="hero-date">${icon('calendar')}${formatShowDate(g.date)}<span>•</span>${g.plan.blocks.filter(b=>b.type==='round').length} rondes</div><div class="button-row">${this.btn('Bereid je show voor',()=>this.go('prepare'),'gold','arrow')}${this.btn('Open regie',()=>this.go('live'),'hero-outline','screen')}</div></div><div class="hero-signature">MET ${showBrand(g).name.toUpperCase()} <span>✦</span></div></section><section class="panel readiness"><div class="panel-heading"><h2>Klaar voor de show?</h2><span class="count-pill">${readiness(g).filter(c=>c.done).length}/3</span></div><p>Van voorbereiding naar applaus.</p><div class="readiness-items">${readiness(g).map(c=>html`<button @click=${()=>this.go(c.id==='plan'?'prepare':'books')}><span class="check-circle ${c.done?'done':''}">${c.done?icon('check'):icon('clock')}</span><span><strong>${c.title}</strong><small>${c.detail}</small></span>${icon('chevron')}</button>`)}</div><button class="check-link" @click=${()=>{this.go('prepare');this.tab='check';}}>Bekijk de showcheck ${icon('arrow')}</button></section></div>
 <div class="stats-grid">${[[icon('calendar'),g.plan.blocks.filter(b=>b.type==='round').length,'Bingorondes','3 rondes + een feestelijke finale'],[icon('book'),g.books.length,'Unieke boekjes','Eén boekje voor de hele show'],[icon('users'),g.books.filter(b=>b.accountId).length,'Gekoppelde boekjes','Spelers met hun eigen geluksnummers'],[icon('gift'),g.plan.blocks.filter(b=>b.type==='round').reduce((n,r)=>n+r.goals.length,0),'Prijsmomenten','Een prijs bij elk winnend patroon']].map(([i,n,t,s])=>html`<article class="stat"><div>${i}<span>${t}</span></div><strong>${n.toString().padStart(2,'0')}</strong><small>${s}</small></article>`)}</div>
 <div class="lower-grid"><section class="panel"><div class="panel-heading"><div><span class="eyebrow">DRAAIBOEK</span><h2>Het verhaal van jouw show</h2></div><button class="text-button" @click=${()=>this.go('prepare')}>Bewerken ${icon('arrow')}</button></div><div class="round-preview">${g.plan.blocks.filter(b=>b.type==='round').map((r,i)=>html`<button class="round-preview-card" @click=${()=>{this.tab='rondes';this.go('prepare');}}><span class="round-tag ${i===3?'finale':''}">${i===3?icon('spark'):'0'+(i+1)}</span><strong>${r.title}</strong><span>${r.goals.length} ${r.goals.length===1?'patroon':'patronen'}</span><div>${mini(g.plan.patterns.find(p=>p.id===r.goals[0].patternId))}</div>${i===3?html`<small>De grote afsluiting</small>`:html`<small>Hoeken → rijen → vol</small>`}</button>`)}</div></section><section class="experience-card"><span class="eyebrow">KIJK DOOR HUN OGEN</span><div class="phone-mini"><div class="phone-top"></div><span>Hoi, Noor!</span><strong>Klaar voor<br>Rocco?</strong><div class="mini-numbers">${[8,24,37,53,72].map(n=>html`<i>${n}</i>`)}</div><b>BINGO!</b></div><h2>Zo beleven je spelers de show.</h2><p>Een fijne plek voor het hele gezin.<br>Boekje koppelen, meespelen, genieten.</p><button @click=${()=>this.go('player')}>Bekijk de spelersapp ${icon('arrow')}</button></section></div>`}`;}
 shows(){return html`${this.heading('VAN IDEE TOT APPLAUS','Mijn shows','Iedere show heeft zijn eigen draaiboek, boekjes en uitslagen.',this.btn('Nieuwe show',()=>this.modal='create','primary','plus'))}<div class="panel"><div class="table-toolbar"><div class="filter-tabs">${[['all','Alle shows'],['draft','Voorbereiding'],['running','Bezig'],['finished','Afgelopen']].map(([v,t])=>html`<button class=${this.filter===v?'active':''} @click=${()=>this.filter=v}>${t}</button>`)}</div><label class="search">${icon('search')}<input placeholder="Zoek een show…" .value=${this.search} @input=${e=>this.search=e.target.value}></label></div><div class="show-list">${this.games.filter(g=>(this.filter==='all'||g.status===this.filter)&&g.title.toLowerCase().includes(this.search.toLowerCase())).map(g=>html`<button class="show-row" @click=${()=>this.task(async()=>{if(!this.demo)await this.selectGame(g.id);this.go('prepare');})}><img src=${showBrand(g).mascot} alt=${showBrand(g).name}><div><strong>${g.title}</strong><small>${formatShowDate(g.date)} · ${showBrand(g).name}</small></div><div class="show-metrics"><span>${g.roundCount} rondes</span><span>${g.bookCount} boekjes</span></div><span class="badge ${g.status==='running'?'green':''}">${status(g.status)}</span>${icon('arrow')}</button>`)}</div>${!this.games.length?this.noGame():nothing}</div>`;}
 prepare(){const g=this.draft||this.game;if(!g)return this.noGame();const locked=g.status!=='draft'&&!this.demo;return html`${this.heading('JOUW SHOWDOSSIER',g.title,formatShowDate(g.date)+' · '+showBrand(g).name,html`${this.dirty?this.btn('Annuleren',()=>{this.draft=null;this.dirty=false;}):nothing}${this.btn(this.dirty?'Wijzigingen opslaan':'Opgeslagen',()=>this.save(),this.dirty?'primary':'secondary',this.dirty?'download':'check',!this.dirty)}${this.btn('Naar de regie',()=>this.go('live'),'primary','screen',this.dirty)}`)}<div class="panel show-dossier"><nav class="attached-tabs" aria-label="Showonderdelen">${[['draaiboek','Draaiboek'],['rondes','Rondes & prijzen'],['regels','Spelregels'],['check','Showcheck']].map(([v,t])=>html`<button class=${this.tab===v?'active':''} @click=${()=>this.tab=v}>${t}${v==='check'?html`<span>${readiness(g).filter(c=>c.done).length}/3</span>`:nothing}</button>`)}</nav><div class="dossier-body">${locked?html`<div class="notice">${icon('info')}Deze show is ${g.status==='finished'?'afgelopen':'gestart'}. De spelregels en ronde-indeling staan vast.</div>`:nothing}${this.tab==='draaiboek'?this.timeline(g,locked):this.tab==='rondes'?this.rounds(g,locked):this.tab==='regels'?this.rules(g,locked):this.showCheck(g)}</div></div>`;}
 timeline(g,locked){return html`<div class="section-head"><div><h2>Van welkom tot grote finale</h2><p>Elk moment op de juiste plek. Klik op een blok om het te bewerken.</p></div>${this.btn('Moment toevoegen',()=>this.modal='block','secondary','plus',locked)}</div><div class="timeline-layout"><div class="timeline">${g.plan.blocks.map((b,i)=>html`<article class="timeline-item ${b.type==='round'?'is-round':''}" draggable=${!locked} @dragstart=${e=>e.dataTransfer.setData('text/plain',String(i))} @dragover=${e=>e.preventDefault()} @drop=${e=>{e.preventDefault();this.moveBlock(Number(e.dataTransfer.getData('text/plain')),i);}}><span class="timeline-index">${String(i+1).padStart(2,'0')}</span><span class="timeline-icon">${icon(b.type==='round'?'grid':b.type==='pause'?'pause':b.type==='countdown'?'clock':b.type==='finale'?'spark':'music')}</span><button class="timeline-copy" @click=${()=>{this.editBlock=i;this.modal='edit-block';}}><strong>${b.title}</strong><small>${b.type==='round'?b.goals.length+' patronen · '+(b.interval||4)+' sec tussen ballen':b.seconds?b.seconds+' seconden':b.text?.slice(0,100)||'Showmoment'}</small></button><div class="order-actions"><button aria-label=${b.title+' omhoog'} @click=${()=>this.moveBlock(i,i-1)} ?disabled=${locked||i===0}>${icon('up')}</button><button aria-label=${b.title+' omlaag'} @click=${()=>this.moveBlock(i,i+1)} ?disabled=${locked||i===g.plan.blocks.length-1}>${icon('down')}</button></div></article>`)}</div><aside class="timeline-help"><span class="eyebrow">EEN FIJNE SHOWFLOW</span><h3>Geef de magie<br>de ruimte.</h3><p>Drie bingorondes, kleine pauzes en een grote finale. Zo blijft de show voor kinderen te volgen.</p><div class="flow-line"><i>01</i><span>Welkom & uitleg</span></div><div class="flow-line"><i>02</i><span>Spelen & samen juichen</span></div><div class="flow-line"><i>03</i><span>Een gouden afsluiting</span></div><hr><p class="small-copy">Rondekaarten blijven bij dezelfde ronde. Een volle kaart is altijd het laatste patroon.</p></aside></div>`;}
 moveBlock(from,to){const g=this.edit();if(!g||to<0||to>=g.plan.blocks.length||from===to)return;const a=g.plan.blocks[from],b=g.plan.blocks[to];if(g.books.length&&a.type==='round'&&g.plan.blocks.slice(Math.min(from,to),Math.max(from,to)+1).filter(x=>x.type==='round').length>1){this.error='De rondevolgorde staat vast omdat er boekjes zijn. Je kunt andere showmomenten wel verplaatsen.';return;}g.plan.blocks.splice(to,0,g.plan.blocks.splice(from,1)[0]);this.requestUpdate();}
 rounds(g,locked){return html`<div class="section-head"><div><h2>Eén kaart. Meerdere geluksmomenten.</h2><p>Een nieuw bord per ronde. Binnen een ronde blijven alle getrokken nummers staan.</p></div></div><div class="rounds-editor">${g.plan.blocks.filter(b=>b.type==='round').map((r,i)=>html`<section class="round-edit"><header><span class="round-tag ${i===3?'finale':''}">${String(i+1).padStart(2,'0')}</span><div><h3>${r.title}</h3><small>${r.goals.length} prijsmomenten</small></div></header><div class="goals">${r.goals.map((goal,j)=>html`<div class="goal">${mini(g.plan.patterns.find(p=>p.id===goal.patternId))}<div><label>Patroon ${j+1}<select .value=${goal.patternId} ?disabled=${locked} @change=${e=>{this.edit().plan.blocks.find(b=>b.id===r.id).goals[j].patternId=e.target.value;this.requestUpdate();}}>${g.plan.patterns.map(p=>html`<option value=${p.id}>${p.title}</option>`)}</select></label><label>Prijs<select .value=${goal.prizeId} ?disabled=${locked} @change=${e=>{this.edit().plan.blocks.find(b=>b.id===r.id).goals[j].prizeId=e.target.value;this.requestUpdate();}}>${g.plan.prizes.map(p=>html`<option value=${p.id}>${p.title}</option>`)}</select></label></div></div>`)}</div></section>`)}</div><div class="section-head"><div><h2>De prijzenpot</h2><p>Deze prijzen gebruik je bij de patronen hierboven.</p></div>${this.btn('Prijs toevoegen',()=>this.modal='prize','secondary','plus',locked)}</div><div class="prize-editor">${g.plan.prizes.map(p=>html`<label class="prize-field"><span class="prize-visual">${icon('gift')}</span><span>Prijsnaam<input .value=${p.title} maxlength="90" ?disabled=${locked} @input=${e=>{this.edit().plan.prizes.find(x=>x.id===p.id).title=e.target.value;}}></span></label>`)}</div>`;}
 rules(g,locked){return html`<div class="section-head"><div><h2>Duidelijke regels voor iedereen</h2><p>Stel dit in vóór de show. De spelserver bewaakt deze regels tijdens het spelen.</p></div></div><div class="settings-grid">${[['claimSeconds','Meldvenster','Iedereen krijgt tijd om een bingo te melden. Minimaal 30 seconden.',30,600],['retroBalls','Terugkijkmarge','Hoeveel trekkingen terug een bingo geldig mag zijn.',0,75],['cooldownSeconds','Afkoeling in seconden','Na een onjuiste bingo geldt dit voor het hele account.',0,86400],['falseLimit','Blokkeren na onjuiste bingo’s','De host kan een account tijdens de show deblokkeren.',1,100]].map(([key,title,help,min,max])=>html`<label class="setting-field"><strong>${title}</strong><small>${help}</small><input type="number" min=${min} max=${max} .value=${String(g.settings[key])} ?disabled=${locked} @change=${e=>{if(!e.target.checkValidity()){e.target.reportValidity();return;}this.edit().settings[key]=Number(e.target.value);}}></label>`)}<label class="setting-field"><strong>Uitzending</strong><small>Vul de 11 tekens van je YouTube-video-ID in.</small><input .value=${g.settings.youtubeId||''} placeholder="Bijvoorbeeld abcdefghijk" maxlength="11" ?disabled=${locked} @input=${e=>{this.edit().settings.youtubeId=e.target.value;}}></label><label class="setting-field"><strong>Showbediening</strong><small>Begeleid geeft je de controle over de voortgang.</small><select .value=${g.settings.mode} ?disabled=${locked} @change=${e=>{this.edit().settings.mode=e.target.value;}}><option value="guided">Begeleid</option><option value="manual">Handmatig</option><option value="auto">Automatisch</option></select></label></div><div class="notice">${icon('book')}Boekjes horen bij één show. Ongebruikte boekjes kunnen niet opnieuw worden ingezet.</div>`;}
 showCheck(g){return html`<div class="section-head"><div><h2>Met een gerust gevoel het podium op</h2><p>Controleer de voorbereiding en doe een korte technische repetitie.</p></div></div><div class="launch-grid"><div>${readiness(g).map(c=>html`<div class="launch-item"><span class="check-circle ${c.done?'done':''}">${icon(c.done?'check':'clock')}</span><div><strong>${c.title}</strong><p>${c.detail}</p></div>${this.btn('Bekijken',()=>this.go(c.id==='plan'?'prepare':'books'))}</div>`)}<div class="launch-item"><span class="check-circle">${icon('music')}</span><div><strong>Stem & geluid beluisteren</strong><p>Controleer het volume in je echte uitzending.</p></div>${this.btn('Steminstellingen',()=>this.openRegie('vlampie'))}</div><div class="launch-item"><span class="check-circle">${icon('screen')}</span><div><strong>Beeld in OBS controleren</strong><p>Test het 16:9-beeld en geluid op je uitzendapparaat.</p></div>${this.btn('Open showvenster',()=>window.open(this.demo?'/?demo=1&screen=1':'/regie?view=show','_blank','noopener'))}</div></div><aside class="launch-summary"><span class="eyebrow">DE LAATSTE CHECK</span><h3>Jij bent<br>de regisseur.</h3><p>Open de regie, loop de scènes door en controleer de spelersapp voordat de eerste bal valt.</p>${this.btn('Naar de regie',()=>this.go('live'),'gold','play',this.dirty)}<small>${this.demo?'Je oefent met voorbeeldgegevens.':'Een echte show start pas na jouw actie in de regie.'}</small></aside></div>`;}
 books(){const g=this.game;if(!g)return this.noGame();let rows=g.books.filter(b=>(b.name+' '+b.code).toLowerCase().includes(this.search.toLowerCase())&&(this.filter==='linked'?b.accountId:this.filter==='unlinked'?!b.accountId:true));return html`${this.heading('IEDEREEN ZIJN EIGEN GELUK','Boekjes & spelers',g.title,html`${this.btn('Spelerslink kopiëren',()=>this.copyLink(),'secondary','users')}${this.btn('Boekjes genereren',()=>this.modal='generate','primary','plus',g.status!=='draft')}`)}<div class="book-summary"><div><strong>${g.books.length}</strong><span>Boekjes</span></div><div><strong>${g.books.filter(b=>b.accountId).length}</strong><span>Gekoppeld</span></div><div><strong>${g.books.filter(b=>!b.accountId).length}</strong><span>Nog beschikbaar</span></div><div><strong>${new Set(g.books.filter(b=>b.accountId).map(b=>b.accountId)).size}</strong><span>Gezinnen</span></div></div><div class="panel"><div class="table-toolbar"><div class="filter-tabs">${[['all','Alle boekjes'],['linked','Gekoppeld'],['unlinked','Beschikbaar']].map(([v,t])=>html`<button class=${this.filter===v?'active':''} @click=${()=>this.filter=v}>${t}</button>`)}</div><label class="search">${icon('search')}<input placeholder="Zoek naam of boekjescode…" .value=${this.search} @input=${e=>this.search=e.target.value}></label></div><div class="table-scroll"><table><thead><tr><th>Speler</th><th>Boekjescode</th><th>Lotnummer</th><th>Status</th><th>Acties</th></tr></thead><tbody>${rows.slice(0,100).map((b,i)=>html`<tr><td><div class="person-cell"><span class="avatar pastel-${i%4}">${b.name?b.name.slice(0,1):'–'}</span><div><strong>${b.name||'Nog niet gekoppeld'}</strong><small>${b.name?'Speler':'Klaar om uit te delen'}</small></div></div></td><td><code>${b.code.slice(0,4)}-${b.code.slice(4)}</code></td><td>#${b.ticket}</td><td><span class="badge ${b.accountId?'green':''}">${b.revokedAt?'Ingetrokken':b.accountId?'Gekoppeld':'Beschikbaar'}</span></td><td><button class="text-button" @click=${()=>{this.selectedBook=g.books.indexOf(b);this.modal='book';}}>Bekijk kaart ${icon('chevron')}</button></td></tr>`)}</tbody></table></div>${!rows.length?html`<div class="empty small"><h3>Geen boekjes gevonden</h3><p>Pas je zoekopdracht aan of maak een nieuwe batch.</p></div>`:nothing}${rows.length>100?html`<p class="table-note">Eerste 100 resultaten. Zoek op naam of code voor een specifiek boekje.</p>`:nothing}</div><div class="section-head"><div><h2>Printbatches</h2><p>Dezelfde unieke kaarten, in kleur of zwart-wit.</p></div></div><div class="batch-list">${g.batches.map((b,i)=>html`<div class="batch-card"><span class="batch-icon">${icon('book')}</span><div><strong>Batch ${String(i+1).padStart(2,'0')}</strong><small>${b.bookIds.length} boekjes · ${g.plan.blocks.filter(b=>b.type==='round').length} kaarten per boekje</small></div>${this.demo?this.btn('Printvoorbeeld',()=>{this.selectedBook=0;this.modal='book';},'secondary','screen'):html`<a class="btn secondary" href=${'/api/bingo/games/'+g.id+'/batches/'+b.id+'/pdf?mode=color'}>${icon('download')}Kleur</a><a class="btn secondary" href=${'/api/bingo/games/'+g.id+'/batches/'+b.id+'/pdf?mode=mono'}>${icon('download')}Zwart-wit</a>`}</div>`)}</div>`;}
 async copyLink(){try{await navigator.clipboard.writeText(location.origin+(this.demo?'/?demo=1#player':'/spelen?spel='+this.game.id));this.message='Spelerslink gekopieerd.';}catch{this.modal='link';}}
 library(){const g=this.game;return html`${this.heading('EEN WERELD VOL SHOW','Showbibliotheek','Jouw presentatoren, patronen en beslisspellen. Klaar om te schitteren.')}<div class="panel"><nav class="attached-tabs">${[['hosts','Presentatoren'],['patterns','Patronen'],['games','Beslisspellen']].map(([id,t])=>html`<button class=${this.libraryTab===id?'active':''} @click=${()=>this.libraryTab=id}>${t}</button>`)}</nav><div class="dossier-body">${this.libraryTab==='hosts'?html`<div class="host-grid">${['rocco','vlampie','milo'].map(id=>{const b=showBrand(id);return html`<article class="host-card"><img src=${b.mascot} alt=${b.name}><div class="host-caption"><span class="eyebrow">${b.studio}</span><h2>${b.name}</h2><p>${b.signature}</p><a class="btn hero-outline" href=${'/regie#studio'}>Studio bekijken ${icon('arrow')}</a></div>${g?.brandId===id?html`<span class="host-active">${icon('check')}Host van deze show</span>`:nothing}</article>`;})}</div>`:this.libraryTab==='patterns'?html`<div class="pattern-library">${(g?.plan.patterns||[]).map(p=>html`<article>${mini(p)}<h3>${p.title}</h3><p>${p.variant==='rows'?'Eén complete horizontale rij.':p.variant==='doubleRows'?'Twee complete horizontale rijen.':p.cells.length===25?'Alle getallen van de kaart.':p.cells.length===4?'De vier buitenste hoeken.':'Streep de gemarkeerde vakjes af.'}</p><span class="badge">Middenvak vrij</span></article>`)}</div>${!g?this.noGame():nothing}`:html`<div class="game-library">${MINIGAMES.map((m,i)=>html`<article><div class="game-art" style=${'background-image:url(/assets/hosts/rocco-games.webp);background-position:'+((i%2)*100)+'% '+((Math.floor(i/2)%2)*100)+'%'}><span>${String(i+1).padStart(2,'0')}</span></div><h3>${m.name.replaceAll('Vlampie','Rocco')}</h3><p>${m.description}</p><a class="text-button" href="/regie#spellen">Bekijk in de studio ${icon('arrow')}</a></article>`)}</div><div class="notice">${icon('info')}Bij gelijke geldige bingo’s wordt de winnaar op de spelserver bepaald. Het beslisspel toont de uitkomst.</div>`}</div></div>`;}
 settings(){return html`${this.heading('DE BASIS ACHTER DE SHOW','Studio-instellingen','Zet je studio één keer goed klaar. Je showinstellingen staan in het showdossier.')}<div class="integration-grid">${[['music','Stem & presentator','Stemprofielen, presentatieteksten en bestaande AI-koppeling.','vlampie','Stemstudio openen'],['screen','Studio & uitzending','Rocco’s decor, camerashots, OBS-venster en transparante overlay.','studio','Beeldstudio openen'],['users','Spelerslogin & e-mail','E-mailcodes en afzenderinstellingen voor ouders en spelers.','koppeling','Logininstellingen openen'],['gift','Presentatieprofielen','Spelregels, uitspraken en presentatiestijl voor ieder showmoment.','spelregels','Profielen openen']].map(([i,t,c,r,a])=>html`<article class="panel integration"><span class="integration-icon">${icon(i)}</span><h2>${t}</h2><p>${c}</p><a class="btn secondary" href=${'/regie#'+r}>${a}${icon('arrow')}</a></article>`)}</div><div class="notice">${icon('info')}De Site is momenteel privé. Een geslaagde repetitie met externe ouders en kinderen is nodig voordat je publiek gaat spelen.</div>`;}
 stage(){const g=this.game,goal=activeGoal(g),number=g.state.drawn.at(-1),scene=this.data?.scene||'welkom',result=g.results.at(-1);return html`<div class="broadcast-stage scene-${scene}"><img class="stage-photo" src=${g.brandId==='vlampie'?'/assets/studio-master-v14.png':'/assets/hosts/'+g.brandId+'-'+this.shot+'-v36.webp'} alt=${showBrand(g).name+' in de studio'}><div class="stage-shade"></div><div class="stage-bug">${showBrand(g).short.toUpperCase()}<span>BINGOSHOW</span><i>✦</i></div><span class="stage-live">${g.status==='running'?'DE SHOW':'WELKOM'}</span>${scene==='bingo'?html`<div class="stage-number"><span>DE LAATSTE BAL</span><strong>${number||'–'}</strong><small>${goal?.round.title||'Ronde 1'}</small></div><div class="stage-pattern">${mini(goal?.pattern)}<div><small>WE SPELEN VOOR</small><strong>${goal?.pattern.title||'Vier hoeken'}</strong></div></div>`:scene==='pauze'?html`<div class="stage-center"><span>EVEN DE BENEN STREKKEN</span><h2>We zijn zo terug!</h2><p>Bewaar je boekje. De volgende ronde komt eraan.</p></div>`:scene==='winnaar'?html`<div class="stage-center winner"><span>APPLAUS VOOR</span><h2>${result?.winner.name||'onze spelers'}!</h2><p>${result?.prize.title||'Jullie maken de show bijzonder.'}</p><div>✦ ✧ ✦</div></div>`:scene==='patroon'?html`<div class="stage-center pattern-scene">${mini(goal?.pattern||g.plan.patterns[0])}<h2>${goal?.pattern.title||g.plan.patterns[0].title}</h2><p>Deze vakjes moeten allemaal zijn afgestreept.</p></div>`:html`<div class="stage-center welcome"><span>DE GORDIJNEN GAAN OPEN</span><h2>Zijn jullie er<br>klaar voor?</h2><p>Pak je boekje. Rocco maakt er een feestje van.</p></div>`}</div>`;}
 live(){const g=this.game;if(!g)return this.noGame();const s=g.state,goal=activeGoal(g),w=s.window,seconds=w?.status==='open'?Math.max(0,Math.ceil((w.endsAt-this.now)/1000)):0;return html`${this.heading('DE REGIEKAMER','Jij hebt de show in handen.',g.title,html`${this.btn('Showvenster',()=>window.open('/?demo=1&screen=1','_blank','noopener'),'secondary','screen')}${this.btn('Spelersapp',()=>this.go('player'),'secondary','users')}`)}<div class="live-status-bar"><span class="badge ${g.status==='running'?'green':''}">${status(g.status)}</span><strong>${goal?.round.title||'Het doek gaat zo open'}</strong><span>${goal?.pattern.title||'Start de oefenshow om te spelen'}</span><span class="live-status-end">${s.drawn.length} / 75 ballen</span></div><div class="regie-layout"><div class="regie-main"><section class="panel program"><div class="monitor-label"><span><i></i>PROGRAMMA</span><small>16:9 · Oefenuitzending</small></div>${this.stage()}<div class="shot-bar"><span>Camera</span>${[['master','Studio'],['desk','Rocco'],['machine','Bingomolen']].map(([s,t])=>html`<button class=${this.shot===s?'active':''} @click=${()=>this.shot=s}>${t}</button>`)}</div></section><div class="scene-grid">${[['welkom','Opening','spark'],['bingo','Bingo','grid'],['patroon','Patroon','book'],['pauze','Pauze','pause'],['winnaar','Winnaar','gift']].map(([sc,t,i])=>html`<button class=${this.data.scene===sc?'active':''} @click=${()=>{this.data.scene=sc;this.persist();}}>${icon(i)}<strong>${t}</strong><small>${this.data.scene===sc?'In beeld':'Zet in beeld'}</small></button>`)}</div><div class="regie-actions">${g.status==='draft'?this.btn('Start oefenshow',()=>this.task(()=>demoStart(this.data),'De oefenshow is gestart.'),'primary','play'):this.btn('Volgende bal',()=>this.task(()=>demoDraw(this.data)),'primary','plus',s.phase!=='running'||s.paused||s.goalWon||g.status==='finished')}${this.btn(s.paused?'Hervat':'Pauzeer',()=>{s.paused=!s.paused;this.persist();},'secondary',s.paused?'play':'pause',g.status!=='running'||s.phase!=='running')}${this.btn('Test bingomelding',()=>{this.selectedBook=0;this.modal='claim';},'secondary','gift',g.status!=='running'||s.goalWon||s.phase==='result')}${s.goalWon?this.btn('Volgend patroon',()=>this.task(()=>demoAdvance(this.data)),'gold','arrow'):nothing}</div><section class="panel"><div class="panel-heading"><h2>Getrokken nummers</h2><span class="muted">${s.drawn.length} van 75</span></div><div class="number-board">${Array.from({length:75},(_,i)=>html`<span class=${s.drawn.at(-1)===i+1?'latest':s.drawn.includes(i+1)?'called':''}>${i+1}</span>`)}</div></section></div><aside class="regie-side"><section class="panel current-goal"><span class="eyebrow">HET ACTIEVE PATROON</span><div>${mini(goal?.pattern||g.plan.patterns[0])}<div><h2>${goal?.pattern.title||'Vier hoeken'}</h2><p>${goal?.prize.title||g.plan.prizes[0].title}</p></div></div><small>Patroon ${(s.goalIndex||0)+1} van ${goal?.round.goals.length||3} · middenvak vrij</small></section><section class="panel claim-panel"><div class="panel-heading"><h2>Bingomeldingen</h2><span class="count-pill">${w?.claims.length||0}</span></div>${w?.status==='open'?html`<div class="window-timer"><span>Meldvenster open</span><strong>${seconds}<small>sec</small></strong><p>De trekking wacht. Iedereen krijgt tijd.</p>${this.btn('+15 seconden',()=>{w.endsAt+=15000;this.persist();},'secondary','clock')}</div>`:html`<p class="muted">${s.phase==='result'?'De kaart is gecontroleerd. Vier de winnaar!':'Nieuwe meldingen verschijnen hier. De kaartcontrole gebeurt automatisch.'}</p>`}${w?.claims.map(c=>html`<div class="claim-result"><span class="avatar">${c.name[0]}</span><div><strong>${c.name}</strong><small>#${c.ticket}</small></div><span class="badge ${c.status==='valid'?'green':'red'}">${{valid:'Geldige bingo',false:'Nog geen bingo',late:'Te laat'}[c.status]}</span></div>`)}${s.phase==='result'?html`${this.btn('Vier de winnaar',()=>{this.data.scene='winnaar';this.persist();},'gold','spark')}`:nothing}</section><section class="panel regie-chat"><div class="panel-heading"><h2>Publiekschat</h2><span class="badge">Oefenen</span></div><div class="chat-messages">${this.data.chat.map(m=>html`<div><span class="avatar small">${m.name[0]}</span><p><strong>${m.name}</strong>${m.text}</p></div>`)}</div><form @submit=${e=>{e.preventDefault();const input=e.target.elements.message;if(input.value.trim()){this.data.chat.push({name:'Rocco',text:input.value.trim()});input.value='';this.persist();}}}><input name="message" placeholder="Een bericht van Rocco…" maxlength="200" required><button class="icon-button" aria-label="Bericht plaatsen">${icon('arrow')}</button></form></section></aside></div>`;}
 player(){const g=this.game;if(!g)return this.noGame();const books=g.books.filter(b=>b.accountId==='demo-0'),b=books[this.selectedBook%Math.max(books.length,1)]||books[0],goal=activeGoal(g),round=Math.max(0,g.state.roundIndex),card=b?.cards[round]||[];return html`${this.heading('DE ERVARING VOOR HET GEZIN','Klein scherm. Groot plezier.','Een interactieve voorvertoning van de spelerservaring.',this.btn('Terug naar de regie',()=>this.go('live'),'secondary','screen'))}<div class="player-demo-layout"><aside class="player-story"><span class="eyebrow">SAMEN MET ROCCO</span><h2>Alles wat ze nodig hebben.<br><em>Precies op tijd.</em></h2><p>Eén ouderaccount voor het gezin. Elk kind zijn eigen boekje en een grote BINGO-knop wanneer het telt.</p><div class="story-point"><span>01</span><div><strong>Een warm welkom</strong><p>Direct zien welke show klaarstaat.</p></div></div><div class="story-point"><span>02</span><div><strong>Iedereen zijn eigen kaart</strong><p>Wissel eenvoudig tussen de kinderen.</p></div></div><div class="story-point"><span>03</span><div><strong>Een duidelijk bingomoment</strong><p>Eerst bevestigen, dan het juiste boekje kiezen.</p></div></div><div class="notice">${icon('info')}Dit is de oefenapp. De echte spelersapp gebruikt e-mailcodes en opgeslagen boekjes.</div><a class="text-button" href="/spelen">Open de echte spelersapp ${icon('arrow')}</a></aside><div class="demo-phone"><div class="device-speaker"></div><header><span class="rocco-wordmark">ROCCO<span>ROYALE</span></span><span class="avatar">N</span></header><div class="phone-body">${this.playerTab==='show'?html`<span class="eyebrow">LEUK DAT JULLIE ER ZIJN</span><h2>Hoi, Noor & Sam! <span>✦</span></h2><p>Klaar voor een beetje bingomagie?</p><div class="player-hero"><img src="/assets/hosts/rocco-mascot.webp" alt="Rocco Royale"><div><span>JOUW SHOW</span><h3>Rocco’s grote<br>kinderbingo</h3><small>4 rondes · samen genieten</small></div><span class="badge gold">${status(g.status)}</span></div><div class="phone-info"><strong>${g.status==='running'?'We spelen nu: '+goal?.pattern.title:'Je boekjes staan klaar!'}</strong><p>${g.status==='running'?goal?.round.title:'Pak de stiften en schuif gezellig aan.'}</p></div><button class="phone-primary" @click=${()=>this.playerTab='boekjes'}>Mijn boekjes bekijken ${icon('arrow')}</button>${g.status==='draft'?html`<button class="phone-text" @click=${()=>this.task(()=>demoStart(this.data))}>Start de oefenshow</button>`:html`<button class="phone-bingo" @click=${()=>{this.selectedBook=0;this.modal='claim';}} ?disabled=${g.status!=='running'||g.state.goalWon}>BINGO!</button>`}`:this.playerTab==='boekjes'?html`<span class="eyebrow">JOUW GELUKSNUMMERS</span><h2>Mijn boekjes</h2><div class="player-selector">${books.map((b,i)=>html`<button class=${i===this.selectedBook%books.length?'active':''} @click=${()=>this.selectedBook=i}><span>${b.name[0]}</span>${b.name}</button>`)}</div><div class="phone-card"><div><strong>${b?.name||'Speler'}</strong><span>Ronde ${round+1} · #${b?.ticket}</span></div><div class="bingo-letters">${'BINGO'.split('').map(l=>html`<span>${l}</span>`)}</div><div class="play-card">${card.map((n,i)=>{const key=b.id+':'+round,marks=this.data.marks[key]||[];return html`<button class=${i===12?'free':marks.includes(i)?'marked':''} aria-label=${i===12?'Vrij middenvak':n+(marks.includes(i)?', afgestreept':'')} @click=${()=>{if(i===12)return;this.data.marks[key]=marks.includes(i)?marks.filter(x=>x!==i):[...marks,i];this.persist();}}>${i===12?'✦':n}</button>`;})}</div><small>Tik op een getal om het af te strepen.</small></div><button class="phone-bingo" @click=${()=>this.modal='claim'} ?disabled=${g.status!=='running'||g.state.goalWon}>BINGO!</button><p class="phone-note">${g.status==='draft'?'De BINGO-knop gaat open wanneer de show begint.':'Controleer eerst het patroon. De host controleert jouw kaart.'}</p>`:this.playerTab==='spelers'?html`<span class="eyebrow">SAMEN SPELEN</span><h2>Mijn gezin</h2>${books.map(b=>html`<div class="phone-person"><span class="avatar">${b.name[0]}</span><div><strong>${b.name}</strong><small>Boekje ${b.code}</small></div>${icon('check')}</div>`)}<button class="phone-primary" @click=${()=>this.modal='demo-person'}>${icon('plus')}Speler toevoegen</button><button class="phone-text" @click=${()=>this.modal='demo-link'}>Boekje koppelen</button>`:html`<span class="eyebrow">EEN GOUDEN MOMENT</span><h2>Mijn prijzen</h2>${g.results.filter(r=>r.winner.accountId==='demo-0').length?g.results.filter(r=>r.winner.accountId==='demo-0').map(r=>html`<div class="phone-info">${icon('gift')}<h3>${r.prize.title}</h3><p>Gewonnen door ${r.winner.name}</p></div>`):html`<div class="phone-empty">${icon('gift')}<h3>Wie weet straks!</h3><p>Jouw gewonnen prijzen krijgen hier een mooie plek.</p></div>`}`}</div><nav class="phone-nav">${[['show','spark','Show'],['boekjes','book','Boekjes'],['spelers','users','Gezin'],['prijzen','gift','Prijzen']].map(([t,i,n])=>html`<button class=${this.playerTab===t?'active':''} @click=${()=>{this.playerTab=t;this.selectedBook=0;}}>${icon(i)}${n}</button>`)}</nav></div></div>`;}
 analysis(){const findings=[['01','Geen vast vertrekpunt','Het oorspronkelijke dashboard opent direct in de regie. De voorbereiding en de vraag “wat moet ik nu doen?” krijgen geen eigen startpunt.','Een showoverzicht met de volgende show, voortgang en concrete acties.'],['02','Eén show op meerdere plekken','Spellen & boekjes, Showvoorbereiding, Patronen, Prijzen en Spelregels hebben eigen schermen en deels eigen modellen. Het overnemen van een plan is een aparte handeling.','Een showdossier dat rechtstreeks het plan van de geselecteerde show bewerkt.'],['03','Te veel tegelijk in de regie','Programma, chat, scènekeuze, voorvertoning, bingobord, claims, bellen en hostbediening delen één werkvlak met geneste tabbladen.','Voorbereiding buiten de regie. Live de nadruk op uitzending, volgende bal, meldingen en voortgang.'],['04','Gestapelde vormgeving','De oorspronkelijke beheerpagina laadt 14 stylesheets. Meerdere lagen veranderen dezelfde navigatie, afmetingen en responsieve indeling.','Een zelfstandig Lit-component voor de showwerkplek, met één stylesheet en vaste ontwerpvariabelen. De bestaande regie-engine krijgt een herkenbare indeling.'],['05','Spelers vinden hun weg via een menu','Negen bestemmingen zitten in het accountmenu. Voor gezinnen zijn show, boekjes en spelers daardoor onvoldoende zichtbaar.','Vaste navigatie naar Show, Boekjes, Gezin en Prijzen. Extra opties blijven in het accountmenu.'],['06','Sterke logica, weinig zichtbare samenhang','De server ondersteunt al unieke kaarten, claimcontrole, terugkijkmarge, accountbrede sancties en herstelbare trekkingen. De interface maakt dat proces lastig te volgen.','Kaartstatussen, showcheck en een oefenshow met dezelfde spelregels maken het proces inzichtelijk.']];return html`${this.heading('VAN LOSSE FUNCTIES NAAR ÉÉN SHOW','Een duidelijke koers voor de Bingoshow.','Analyse van de bestaande broncode en de vertaling naar dit redesign.')}<section class="analysis-intro"><span class="eyebrow">DE KERN</span><h2>De magie zit vóór de schermen.<br>De rust hoort erachter.</h2><p>Rocco is het gezicht van de kinderbingo. De ouder regelt de deelname, het kind geniet en de host bewaakt de show. Die drie taken verdienen elk een eigen, herkenbare omgeving.</p><div><span>01 <b>Voorbereiden</b></span><span>02 <b>Regisseren</b></span><span>03 <b>Meespelen</b></span></div></section><div class="analysis-findings">${findings.map(([n,t,f,c])=>html`<article class="panel"><span class="finding-number">${n}</span><div><h2>${t}</h2><p>${f}</p><div class="finding-change">${icon('arrow')}<span>${c}</span></div></div></article>`)}</div><div class="lower-grid"><section class="panel analysis-section"><h2>De spelafspraken blijven leidend</h2><ul><li>Vier rondes: drie reguliere rondes en een finale.</li><li>Per ronde één unieke kaart met 25 vakken en een vrij middenvak.</li><li>Vier hoeken → bovenste én onderste rij → volle kaart. De finale speelt voor een volle kaart.</li><li>Een boekje hoort bij één show. De code heeft acht tekens; de laatste vier zijn het lotnummer.</li><li>Eén account beheert meerdere spelers en boekjes.</li><li>Een bevestigde melding stopt de trekking en opent een meldvenster van minimaal 30 seconden.</li><li>De server controleert de kaart. Afkoeling en blokkering gelden voor het account.</li><li>Een volledige kaart sluit de ronde af. Gelijke geldige bingo’s gebruiken het bestaande beslisproces.</li></ul></section><section class="panel analysis-section"><h2>Wat deze versie doet</h2><p><b>Gekoppeld aan de bestaande server:</b> shows laden en maken, showplannen opslaan, boekjes genereren, PDF-batches downloaden en bestaande spelersaccounts gebruiken.</p><p><b>Opnieuw vormgegeven:</b> de showwerkplek, de route naar de regie en de spelersapp. Lit 3 blijft het componentframework; de bestaande Worker, D1 en R2 blijven behouden.</p><p><b>Oefenshow:</b> alleen lokale voorbeeldgegevens. Trekkingen, claims, afkoeling en patroonovergangen gebruiken dezelfde spelregels als de server.</p><p><b>Nog te verifiëren in een echte repetitie:</b> externe toegang, e-mailbezorging, stemprovider, OBS-audio, camerawissels, gelijktijdige spelers en verbindingsherstel. Een lokale oefenshow bewijst deze koppelingen niet.</p></section></div><section class="panel analysis-section"><h2>De route naar je eerste kinderbingo</h2><div class="priority-grid">${[['Eerst','Een volledige generale repetitie','Maak een kleine echte testshow. Laat twee ouderaccounts boekjes koppelen en doorloop meerdere patronen, een onjuiste bingo en gelijke meldingen.'],['Daarna','Een gecontroleerde eerste show','Werk met een vaste voorbereiding, één regisseur en een tweede persoon voor deelnemersvragen en prijsuitgifte.'],['Vervolgens','Gericht uitbreiden','Optimaliseer na de eerste ervaring. Automatische regie, belmomenten en extra minigames zijn uitbreidingen op een betrouwbare basis.']].map(([s,t,p])=>html`<div><span class="badge">${s}</span><h3>${t}</h3><p>${p}</p></div>`)}</div></section>`;}
 renderModal(){const g=this.draft||this.game,book=this.game?.books[this.selectedBook];const close=()=>{this.modal='';};let title='',content=nothing;
 if(this.modal==='create'){title='Een nieuwe show begint hier';content=html`<form @submit=${e=>{e.preventDefault();const f=new FormData(e.target);this.task(async()=>{if(this.demo){const d=createRehearsal();d.game.title=String(f.get('title'));d.game.date=String(f.get('date'));d.game.brandId=String(f.get('brand'));this.data=d;this.game=d.game;}else{const r=await bingoApi('/games',{method:'POST',body:{title:f.get('title'),date:f.get('date'),brandId:f.get('brand'),roundCount:4}});this.game=r.game;this.games=[this.summary(r.game),...this.games];localStorage.setItem('vlampie-selected-game',r.game.id);}this.modal='';this.tab='draaiboek';this.go('prepare');},this.demo?'Nieuwe oefenshow klaargezet.':'Show aangemaakt.');}}><label>Shownaam<input name="title" required maxlength="60" value="Rocco’s grote kinderbingo"></label><div class="form-grid"><label>Datum & tijd<input name="date" type="datetime-local" required value="2026-11-01T14:00"></label><label>Presentator<select name="brand"><option value="rocco">Rocco Royale</option><option value="vlampie">Vlampie</option><option value="milo">Milo Magico</option></select></label></div><div class="notice">${icon('grid')}Je begint met 3 rondes + een finale. De patronen, prijzen en pauzes staan alvast klaar.</div><button class="btn primary" ?disabled=${this.busy}>${icon('plus')}${this.demo?'Nieuwe oefenshow maken':'Show aanmaken'}</button></form>`;}
 if(this.modal==='reset'){title='Een nieuwe repetitie?';content=html`<p>Hiermee wis je alleen de oefenshow in deze browser. Je echte shows blijven bewaard.</p>${this.btn('Begin opnieuw',()=>{this.data=createRehearsal();this.game=this.data.game;this.draft=null;this.dirty=false;this.persist();this.modal='';this.go('overview');},'primary','undo')}`;}
 if(this.modal==='generate'){title='Een stapel geluksmomenten';content=html`<p>Elk boekje krijgt unieke kaarten voor alle rondes, een eigen code en lotnummer.</p><form @submit=${e=>{e.preventDefault();const f=new FormData(e.target);this.task(async()=>{if(this.demo)generateBooks(this.game,Number(f.get('count')),crypto.randomUUID(),Date.now(),{mode:f.get('mode')});else await this.post('generate',{count:Number(f.get('count')),printMode:f.get('mode')});this.modal='';},'Boekjes aangemaakt. Je vindt ze terug bij de printbatches.');}}><div class="form-grid"><label>Aantal boekjes<input name="count" type="number" min="1" max="150" required value="25"></label><label>Printuitvoering<select name="mode"><option value="color">Kleur</option><option value="mono">Zwart-wit</option></select></label></div><button class="btn primary" ?disabled=${this.busy}>${icon('book')}Genereer boekjes</button></form>`;}
 if(this.modal==='link'){title='Deel de spelerslink';content=html`<p>Kopieer deze link om de spelersapp te openen.</p><input readonly .value=${location.origin+(this.demo?'/?demo=1#player':'/spelen?spel='+this.game.id)} @focus=${e=>e.target.select()}>`;}
 if(this.modal==='block'){title='Een nieuw showmoment';content=html`<div class="block-options">${[['pause','Pauze','Even drinken of bewegen.'],['story','Verhaalmoment','Een avontuur met Rocco.'],['explanation','Uitleg','Vertel wat er gaat gebeuren.'],['call','Belmoment','Een gesprek met een speler.']].map(([t,n,c])=>html`<button @click=${()=>{const draft=this.edit();if(draft){const b=createBlock(t,draft.plan);b.title=n;b.text='Rocco: wat gezellig dat jullie er zijn!';draft.plan.blocks.splice(draft.plan.blocks.length-1,0,b);this.modal='';this.requestUpdate();}}}><span>${icon(t==='pause'?'pause':'spark')}</span><strong>${n}</strong><small>${c}</small>${icon('plus')}</button>`)}</div>`;}
 if(this.modal==='edit-block'){const b=g.plan.blocks[this.editBlock],locked=g.status!=='draft'&&!this.demo;title=b.title;content=html`<form @submit=${e=>{e.preventDefault();const f=new FormData(e.target),d=this.edit();if(!d)return;const b=d.plan.blocks[this.editBlock];if(f.has('title'))b.title=String(f.get('title'));if(f.has('text'))b.text=String(f.get('text'));if(f.has('seconds'))b.seconds=Number(f.get('seconds'));if(f.has('interval'))b.interval=Number(f.get('interval'));this.modal='';this.requestUpdate();}}><label>Titel<input name="title" .value=${b.title} required maxlength="60" ?disabled=${locked} ?readonly=${g.books.length>0&&b.type==='round'}></label>${b.text!==undefined?html`<label>Presentatietekst<textarea name="text" rows="4" maxlength="500" required .value=${b.text} ?disabled=${locked}></textarea></label>`:nothing}${b.seconds?html`<label>Duur in seconden<input name="seconds" type="number" min="1" max="86400" .value=${String(b.seconds)} required ?disabled=${locked}></label>`:nothing}${b.type==='round'?html`<label>Tijd tussen ballen in seconden<input name="interval" type="number" min="0" max="60" .value=${String(b.interval)} required ?disabled=${locked}></label><p>Patronen en prijzen stel je in via de tab Rondes & prijzen.</p>`:nothing}${!locked?html`<button class="btn primary">Wijziging toepassen</button>`:nothing}</form>`;}
 if(this.modal==='prize'){title='Voeg een prijs toe';content=html`<form @submit=${e=>{e.preventDefault();const f=new FormData(e.target);this.edit().plan.prizes.push({id:'prijs-'+crypto.randomUUID(),title:String(f.get('title')),description:String(f.get('description')),image:''});this.modal='';this.requestUpdate();}}><label>Prijsnaam<input name="title" required maxlength="90" placeholder="Bijvoorbeeld: creatief knutselpakket"></label><label>Omschrijving<textarea name="description" maxlength="180" rows="3"></textarea></label><button class="btn primary">${icon('plus')}Prijs toevoegen</button></form>`;}
 if(this.modal==='book'&&book){title=book.name?book.name+' · boekje '+book.ticket:'Boekje '+book.ticket;content=html`<p>Code <b>${book.code}</b> · ${this.game.title}</p><div class="book-cards-preview">${book.cards.map((card,r)=>html`<div><h3>${r===3?'Finale':'Ronde '+(r+1)}</h3><div class="bingo-letters">${'BINGO'.split('').map(l=>html`<span>${l}</span>`)}</div><div class="static-card">${card.map((n,i)=>html`<span class=${i===12?'free':''}>${i===12?'✦':n}</span>`)}</div></div>`)}</div>${!this.demo?html`<a class="btn primary" href=${'/api/bingo/games/'+this.game.id+'/books/'+book.id+'/pdf'}>${icon('download')}Download boekje</a>`:html`<p class="small-copy">Oefenkaarten. In je echte show kun je de volledige PDF downloaden.</p>`}`;}
 if(this.modal==='claim'){const playerBooks=this.game.books.filter(b=>b.accountId==='demo-0');title='Heb je echt BINGO?';content=html`<div class="claim-confirm"><span class="claim-spark">✦</span><p>Controleer het actieve patroon. Kies het boekje dat bingo heeft. Na bevestiging stopt de trekking en gaat het meldvenster open.</p><div class="notice">${icon('info')}Oefenmelding · een onvolledige kaart wordt ook in de oefenshow afgekeurd.</div>${playerBooks.map(b=>html`<button class="claim-book-btn" @click=${()=>this.task(()=>{const result=demoClaim(this.data,b.id);this.modal='';this.message=result.status==='valid'?'Bingo ontvangen! Het meldvenster staat open.':result.status==='false'?'Nog geen bingo. Dit account krijgt een korte afkoelperiode.':'Deze bingo valt buiten de terugkijkmarge.';})}><span class="avatar">${b.name[0]}</span><span><strong>${b.name}</strong><small>Boekje #${b.ticket}</small></span><b>Ja, BINGO!</b></button>`)}<button class="phone-text" @click=${close}>Nee, we spelen nog even verder</button></div>`;}
 if(this.modal==='demo-person'){title='Wie speelt er ook mee?';content=html`<form @submit=${e=>{e.preventDefault();const f=new FormData(e.target),b=this.game.books.find(b=>!b.accountId);if(!b){this.error='Geen beschikbare oefenboekjes meer.';return;}Object.assign(b,{accountId:'demo-0',profileId:'profile-'+crypto.randomUUID(),name:String(f.get('name')),age:Number(f.get('age'))});this.persist();this.modal='';this.message='Speler toegevoegd met een oefenboekje.';}}><label>Voornaam<input name="name" required maxlength="40"></label><label>Leeftijd<input name="age" type="number" min="0" max="120" required></label><button class="btn primary">Speler toevoegen</button></form>`;}
 if(this.modal==='demo-link'){title='Koppel een oefenboekje';const available=this.game.books.find(b=>!b.accountId);content=html`<p>Probeer de beschikbare oefencode <b>${available?.code||'Geen beschikbaar'}</b>.</p><form @submit=${e=>{e.preventDefault();const f=new FormData(e.target),b=this.game.books.find(b=>b.code===String(f.get('code')).replace(/[^a-z0-9]/gi,'').toUpperCase());if(!b||b.accountId){this.error='Deze code is niet beschikbaar.';return;}Object.assign(b,{accountId:'demo-0',profileId:'profile-'+crypto.randomUUID(),name:String(f.get('name')),age:7});this.persist();this.modal='';this.message='Boekje gekoppeld.';}}><label>Voornaam<input name="name" required maxlength="40"></label><label>Boekjescode<input name="code" required maxlength="9" autocapitalize="characters"></label><button class="btn primary">Boekje koppelen</button></form>`;}
 return html`<div class="modal-backdrop" @click=${e=>{if(e.target===e.currentTarget)close();}}><section class="modal ${this.modal==='book'?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title" @keydown=${e=>{if(e.key==='Escape')close();if(e.key==='Tab'){const focus=[...e.currentTarget.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href]')];if(e.shiftKey&&document.activeElement===focus[0]){e.preventDefault();focus.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===focus.at(-1)){e.preventDefault();focus[0]?.focus();}}}}><header><span class="eyebrow">VLAMPIE STUDIO</span><button class="icon-button" aria-label="Venster sluiten" @click=${close}>${icon('close')}</button></header><h2 id="modal-title">${title}</h2>${this.error?html`<div class="alert error" role="alert">${this.error}</div>`:nothing}${content}</section></div>`;}
 updated(changed){if(changed.has('modal')&&this.modal){this.querySelector('.modal button, .modal input')?.focus();}if(changed.has('modal')&&!this.modal)this.error='';}
}
customElements.define('studio-hub',StudioHub);
